package co.edu.unicauca.lisw2t5g02.presentation;
import co.edu.unicauca.lisw2t5g02.domain.question.*;import co.edu.unicauca.lisw2t5g02.domain.user.*;import javax.swing.*;import java.awt.*;
public class MainMenuView extends JFrame {private final User user;private final UserService users;private final QuestionService questions;private final QuestionController questionController;public MainMenuView(User u,UserService us,QuestionService qs){super("Banco de Preguntas Saber PRO");user=u;users=us;questions=qs;questionController=new QuestionController(qs);build();setSize(620,430);setLocationRelativeTo(null);setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);}
 private void build(){setLayout(new BorderLayout(10,10));JPanel h=new JPanel(new GridLayout(2,1));h.setBorder(BorderFactory.createEmptyBorder(15,15,5,15));JLabel a=new JLabel("Bienvenido, "+user.getName());a.setFont(a.getFont().deriveFont(Font.BOLD,18f));h.add(a);h.add(new JLabel("Rol: "+user.getRole()));add(h,BorderLayout.NORTH);JPanel p=new JPanel(new GridLayout(0,1,8,8));p.setBorder(BorderFactory.createEmptyBorder(10,30,10,30));if(user.getRole()==Role.AUTOR_PREGUNTAS){JButton crear=new JButton("Crear pregunta (HU-1.1)");crear.addActionListener(e->new CreateQuestionView(questionController,null,user).setVisible(true));p.add(crear);JButton gestionar=new JButton("Mis preguntas (HU-1.2 / HU-1.3)");gestionar.addActionListener(e->new GUIQuestions(questions,user).setVisible(true));p.add(gestionar);}if(user.getRole()==Role.ADMINISTRADOR){JButton admin=new JButton("Asignar revisores (HU-2.1)");admin.addActionListener(e->new AdminReviewView(questions).setVisible(true));p.add(admin);JButton preguntas=new JButton("Consultar preguntas");preguntas.addActionListener(e->new GUIQuestions(questions,user).setVisible(true));p.add(preguntas);JButton usuarios=new JButton("Administración de usuarios");usuarios.addActionListener(e->new UserAdminView(users).setVisible(true));p.add(usuarios);}JButton cerrar=new JButton("Cerrar sesión");cerrar.addActionListener(e->System.exit(0));p.add(cerrar);add(p,BorderLayout.CENTER);}}
